// Why Code: Vapi trimite argumentele în formate variabile; aici le validăm și le normalizăm (o unealtă = un item).
// `route` alege ramura din Switch: numele uneltei sau „direct” (fără bază de date: eligibilitate, erori, unealtă necunoscută).
const msg = $('Webhook vapi-tools').first().json.body?.message ?? {};
if (msg.type !== 'tool-calls') throw new Error('Mesaj Vapi neașteptat: ' + msg.type);
const list = Array.isArray(msg.toolCallList) ? msg.toolCallList : [];
if (!list.length) throw new Error('toolCallList gol');
const callId = msg.call?.id ?? null;
const callerNumber = String(msg.call?.customer?.number ?? '').replace(/\D/g, '');
const asObj = (v) => { if (typeof v === 'string') { try { return JSON.parse(v); } catch { return {}; } } return v ?? {}; };

// Transcrierea vocală scrie județul întreg („Cluj 11 TST”): îl transformăm în prefixul de înmatriculare (CJ11TST).
const COUNTIES = { ALBA:'AB', ARAD:'AR', ARGES:'AG', BACAU:'BC', BIHOR:'BH', BISTRITA:'BN', BOTOSANI:'BT', BRAILA:'BR', BRASOV:'BV', BUZAU:'BZ', CALARASI:'CL', CARAS:'CS', CLUJ:'CJ', CONSTANTA:'CT', COVASNA:'CV', DAMBOVITA:'DB', DOLJ:'DJ', GALATI:'GL', GIURGIU:'GR', GORJ:'GJ', HARGHITA:'HR', HUNEDOARA:'HD', IALOMITA:'IL', IASI:'IS', ILFOV:'IF', MARAMURES:'MM', MEHEDINTI:'MH', MURES:'MS', NEAMT:'NT', OLT:'OT', PRAHOVA:'PH', SALAJ:'SJ', SIBIU:'SB', SUCEAVA:'SV', TELEORMAN:'TR', TIMIS:'TM', TULCEA:'TL', VALCEA:'VL', VASLUI:'VS', VRANCEA:'VN', BUCURESTI:'B' };
const spokenPlate = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().split(/[^A-Z0-9]+/).map((w) => COUNTIES[w] ?? w).join('');

return list.map((t) => {
  const name = t.function?.name ?? t.name ?? '';
  const args = asObj(t.function?.arguments ?? t.arguments ?? t.parameters);
  const item = (extra) => ({ json: { toolCallId: t.id, name, args, callId, route: name, ...extra } });
  const fail = (error) => item({ route: 'direct', error });

  if (name === 'check_eligibility') return item({ route: 'direct' });

  if (name === 'lookup_policy') {
    const plate = spokenPlate(args.plate);
    // Modelul a trimis o dată cifrele telefonului în câmpul plate: 9+ cifre înseamnă telefon.
    const plateDigits = String(args.plate ?? '').replace(/\D/g, '');
    const phone = String(args.phone || (plateDigits.length >= 9 ? plateDigits : '') || callerNumber).replace(/\D/g, '').slice(-9);
    const validPlate = /^[A-Z]{1,2}\d{2,3}[A-Z]{3}$/.test(plate);
    if (!validPlate && phone.length !== 9) return fail('Nu am înțeles numărul. Cere clientului numărul de telefon, cifră cu cifră, sau plăcuța: județul, cifrele, apoi cele trei litere una câte una.');
    return item({ body: { p_plate: validPlate ? plate : '', p_phone: phone } });
  }

  if (name === 'start_claim') {
    const s = (v, n) => String(v ?? '').slice(0, n);
    return item({ body: { entity_type: 'voice_call', type: 'voice.claim_started', payload: { callId, summary: s(args.summary, 500), location: s(args.location, 300), occurred: s(args.occurred, 40), damage: s(args.damage, 300), impact_zone: s(args.impact_zone, 20) } } });
  }

  if (name === 'claim_status') {
    // Transcrierea confundă „B P”, iar modelul reformatează: contează cele 9 cifre, prefixul BP- îl punem noi.
    const digits = String(args.claim_ref ?? '').replace(/\D/g, '');
    if (digits.length !== 9) return fail('Referința are 9 cifre după „B P”, de exemplu 2611 00017. Cere clientului doar cifrele, una câte una.');
    return item({ body: { p_call_id: callId, p_ref: 'BP-' + digits.slice(0, 4) + '-' + digits.slice(4) } });
  }

  if (name === 'escalate_to_human') {
    const reasons = { cere_om: 'clientul cere un om', urgenta: 'urgență / persoane rănite', nemultumit: 'client nemulțumit sau confuz', in_afara_competentei: 'întrebare în afara competenței (juridic, sume)' };
    const reason = reasons[args.reason] ?? 'nespecificat';
    const summary = String(args.summary ?? '').slice(0, 600);
    const callback = String(args.callback_phone ?? '').replace(/[^0-9+]/g, '') || callerNumber;
    const telegramText = ['🔔 Un client cere un om (apel cu Ana)', 'Motiv: ' + reason, summary ? 'Rezumat: ' + summary : null, 'Telefon pentru apel înapoi: ' + (callback || 'nespecificat (apel web)')].filter(Boolean).join('\n');
    return item({ telegramText, body: { channel: 'voice', external_id: callId ?? ('manual-' + Date.now()), handoff_status: 'requested', summary: ('Escaladare: ' + reason + (summary ? '. ' + summary : '')).slice(0, 1000) } });
  }

  return fail('Unealtă necunoscută: ' + name);
});

// Why Code: textele în română pe care Ana le rostește, pentru fiecare unealtă. Toate ramurile din Switch ajung aici.
const p = $('Parse tool calls').item.json;
const out = (result) => ({ toolCallId: p.toolCallId, result: typeof result === 'string' ? result : JSON.stringify(result) });
const err = (error) => ({ toolCallId: p.toolCallId, error });
const rows = () => { const raw = $json.data; if (raw === undefined || raw === '') return []; try { const v = JSON.parse(raw); return Array.isArray(v) ? v : []; } catch { throw new Error('Răspuns Supabase invalid'); } };
const bool = (v) => v === true || /^(da|true|yes|1)$/i.test(String(v ?? ''));
const days = (d) => Math.ceil((new Date(d + 'T23:59:59') - new Date()) / 86400000);
const MONTHS = ['ianuarie', 'februarie', 'martie', 'aprilie', 'mai', 'iunie', 'iulie', 'august', 'septembrie', 'octombrie', 'noiembrie', 'decembrie'];
const dateRo = (d) => { const [y, m, day] = d.split('-').map(Number); return day + ' ' + MONTHS[m - 1] + ' ' + y; };
const TYPES = { RCA: 'R C A', CASCO: 'CASCO', PAD: 'PAD', LOCUINTA: 'de locuință', VIATA: 'de viață', ALTA: 'de asigurare' };
const spell = (s) => String(s).split('-').map((part) => part.split('').join(' ')).join(', ');

let json;
if (p.error) json = err(p.error);
else if ($json.error) json = err(p.name === 'escalate_to_human' ? 'Nu am putut anunța un coleg acum. Cere clientului să sune din nou la agenție.' : 'Nu pot citi datele acum. Propune să anunți un coleg.');
else if (p.name === 'check_eligibility') {
  const a = p.args;
  if (a.injuries === undefined || a.injuries === null || a.injuries === '') json = err('Nu ai aflat dacă există răniți. Întreabă clar „Există persoane rănite?” și cheamă din nou unealta.');
  else if (bool(a.injuries)) json = out({ eligible: false, emergency: true, spune: 'Sunați imediat la 112. Nu continuăm cu amiabila.', urmeaza: 'Propune să anunți un coleg (escaladare, motiv urgență).' });
  else {
    const reasons = [];
    if (!bool(a.twoVehicles)) reasons.push('Amiabila se completează doar când sunt implicate exact două vehicule.');
    if (!bool(a.onlyMaterialDamage)) reasons.push('Amiabila se poate folosi doar pentru pagube materiale, fără răniți.');
    if (!bool(a.bothInsured)) reasons.push('Ambele vehicule trebuie să aibă R C A valabil.');
    if (!bool(a.agreed)) reasons.push('Cei doi șoferi trebuie să fie de acord asupra circumstanțelor; altfel se cheamă poliția.');
    json = reasons.length
      ? out({ eligible: false, spune: reasons[0] + ' Vă recomand să chemați poliția.', urmeaza: 'Propune să anunți un coleg.' })
      : out({ eligible: true, spune: 'Se poate completa amiabila.', urmeaza: 'Întreabă locul, momentul și daunele, apoi pregătește dosarul.' });
  }
} else if (p.name === 'lookup_policy') {
  const list = rows().map((r) => {
    const d = days(r.valid_to);
    const car = [r.make, r.model].filter(Boolean).join(' ');
    const stare = d < 0 ? 'expirată din ' + dateRo(r.valid_to) : 'valabilă până pe ' + dateRo(r.valid_to) + (d <= 30 ? ', adică mai sunt ' + d + (d === 1 ? ' zi' : ' zile') : '');
    return { tip: r.type, asigurator: r.insurer, valabila_pana: r.valid_to, zile_ramase: d, vehicul: car || null,
      spune: 'Aveți o poliță ' + (TYPES[r.type] ?? r.type) + (car ? ' pentru ' + car : '') + ' la ' + r.insurer + ', ' + stare + '.' + (d <= 30 ? ' Brokerul vă poate ajuta cu reînnoirea.' : '') };
  });
  json = list.length
    ? out({ spune: list.slice(0, 3).map((x) => x.spune).join(' ') + (list.length > 3 ? ' Mai aveți încă ' + (list.length - 3) + ' polițe; spuneți-mi dacă vreți detalii despre una anume.' : ''), numar_polite: list.length, polite: list })
    : out({ spune: 'Nu am găsit nicio poliță pentru datele date.', urmeaza: 'Cere o singură dată alt telefon sau propune un coleg.' });
} else if (p.name === 'start_claim') {
  json = out({ started: true, spune: 'Apăsați pe ecran butonul „Continuă cu datele din apel”. Locul și daunele sunt deja completate.', urmeaza: 'Nu ai trimis niciun mesaj. Clientul mai are de adăugat actele și datele celuilalt șofer.' });
} else if (p.name === 'escalate_to_human') {
  json = out({ escalated: true, spune: 'Am anunțat un coleg și i-am trimis rezumatul. Nu trebuie să repetați totul.', urmeaza: 'Nu promite o oră.' });
} else if (p.name === 'claim_status') {
  const r = rows()[0];
  const labels = { draft: 'este o ciornă', awaiting_b: 'așteaptă datele celuilalt șofer', signed: 'este semnat de ambii șoferi', submitted: 'a fost trimis brokerului', in_progress: 'a fost preluat de un broker și e în lucru', closed: 'este închis' };
  json = r ? out({ spune: 'Dosarul ' + spell(r.public_ref) + ' ' + (labels[r.status] ?? r.status) + '.', referinta: r.public_ref, stare: labels[r.status] ?? r.status }) : err('Nu găsesc un dosar cu această referință.');
}
return { json };
